async ({ market: { prices } }) => {
  const today = new Date().toISOString().slice(0, 10);
  const reqs: string[][] = [
    ["SPY", "1994-01-01", "2003-12-31"], ["SPY", "2018-01-01", today],
    ["QQQ", "1999-01-01", "2003-12-31"], ["QQQ", "2018-01-01", today],
  ];
  const r = await Promise.allSettled(reqs.map(([t, s, e]) => prices({ ticker: t, startDate: s, endDate: e, interval: "month" })));
  return { today, res: r.map((x, i) => x.status === "fulfilled" ? { req: reqs[i], provider: x.value.provider, count: x.value.count, url: x.value.url, first: x.value.data[0], last: x.value.data.at(-1) } : { req: reqs[i], err: String(x.reason).slice(0, 300) }) } as PitJsonValue;
}
